import json,pathlib,hashlib,datetime,sys
import jsonschema
R=pathlib.Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'scripts'));from validate import question_hash
D=R/'audits/legacy-concept-closure';load=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
s=load(D/'independent-integration-answer-seal-v1.json');qs=load(D/'qualified-drafts-v1.json')['questions'];a={x['questionId']:x for x in s['answers']};ad=load(R/'audits/lecture-ledger-challenge/L02-L05-independent-adjudication.json');ev={x['physicalPage']:x for x in ad['decisions']};now=datetime.datetime.now(datetime.timezone.utc).isoformat();rs=[]
flags={'W01-L02-Q-106':('difficulty','The stem already defines PCA as projection and clustering as group assignment, then asks the reader to repeat those exact roles. Remove the answer-bearing purpose clauses and test the distinction from a neutral pipeline situation.'),'W01-L02-Q-107':('distractors','The policy-model weights necessarily encoding exactly the printed scene count and physical-scans-only without simulation are conspicuously implausible distractors. Replace them with realistic simulator-versus-loaded-dataset or installed-version/scene-count confusions while retaining the unvalidated100K caveat.'),'W01-L05-Q-081':('assumptions','The question refers to supplied official historical evidence, but the visible stem/assumptions do not supply the historical table; its exact dates appear only in solution/provenance. Put the bounded historical evidence in a pre-answer-readable context, or remove the unsupported supplied-evidence wording and make the recall scope explicit. Do not claim current-release verification.')}
for q in qs:
 assert set(q['correctOptionIds'])==set(a[q['id']]['independentAnswerOptionIds']);p=q['citations'][0]['physicalPage'];e=ev[p];checks={k:True for k in ['sourceSupport','assumptions','answerSet','distractors','calculations','figureFidelity','explanation','difficulty','duplication']};f=flags.get(q['id']);find=[]
 if f:checks[f[0]]=False;find=[f[1]]
 r={'id':'REV-'+q['id']+'-v1-independent-integration','questionId':q['id'],'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':'independent-integration-legacy-v1','decision':'flagged' if f else 'verified','reviewedAt':now,'sourceVersions':{'lectures':ad['sourceSha256']},'reviewedSlideIds':[f'lectures-p{p:04d}'],'independentAnswerOptionIds':a[q['id']]['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':False,'checks':checks,'reasoning':a[q['id']]['reasoning']+' Independently sealed before the generated key reveal; prior source-claim adjudication is disclosed. Full options/explanations and nearest related existing questions were inspected; approved items assess distinct transport, message dimensionality and release-history distinctions. No live ROS/Gazebo execution or browser QA claim.','findings':find,'priorExposure':s['priorExposure'],'reviewType':'independent_qualified_source_review_with_prior_adjudication','blindAnswerRecord':str((D/'independent-integration-answer-seal-v1.json').relative_to(R)),'blindAnswerRecordSha256':sha(D/'independent-integration-answer-seal-v1.json'),'sourceInspectionEvidence':[{'sourceId':'lectures','physicalPage':p,'imagePath':e['visualEvidencePath'],'imageSha256':e['visualEvidenceSha256'],'visualInspection':'complete','viewedAt':ad['reviewedAt'],'inspectionScope':'Prior personal rendered-page inspection for independent adjudication; unchanged source hash checked.'}],'primaryEvidenceScope':e['primaryEvidenceScope'],'primarySourceUrl':e['primarySourceUrl']};jsonschema.validate(r,load(R/'data/schema.review.json'));rs.append(r)
p=D/'independent-review-v1.json';assert not p.exists();p.write_text(json.dumps(rs,ensure_ascii=False,indent=2)+'\n');print(sha(p),len(rs),sum(r['decision']=='verified'for r in rs))
